'use strict';
const art={leaf:'<path d="M5 17C2 9 10 3 21 3c0 11-6 18-14 16"/><path d="M3 22 17 8"/>',ball:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/>',settings:'<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="9" cy="5" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="8" cy="19" r="2" fill="currentColor"/>',next:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 5 5L20 7"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-5 4 3 3-3 5 5"/>',screen:'<rect x="4" y="2" width="16" height="20" rx="3"/><path d="M9 18h6"/>',layers:'<path d="m2 8 10-6 10 6-10 6ZM2 13l10 6 10-6M2 18l10 6 10-6"/>',apps:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',recover:'<path d="M4 9a8 8 0 1 1 0 7M3 3v7h7"/>',position:'<circle cx="12" cy="12" r="7"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',theme:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',update:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',github:'<path d="M9 21v-4c-5 1-5-2-6-3m12 7v-4c0-1 0-2-1-2 4 0 7-2 7-6 0-2-1-3-2-4 0-1 0-2-1-3l-4 2H9L5 2C4 3 4 4 4 5 3 6 3 7 3 9c0 4 2 6 6 6-1 1-1 1-1 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-10v.01"/>',gesture:'<path d="M9 17V6a2 2 0 0 1 4 0v7m0-5a2 2 0 0 1 4 0v6m0-3a2 2 0 0 1 4 0v6c0 4-4 5-7 5-4 0-6-3-8-5l-3-4c-1-2 1-3 3-1l3 3"/>',region:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><rect x="8" y="8" width="8" height="8" rx="1"/>',record:'<rect x="2" y="5" width="14" height="14" rx="3"/><path d="m16 10 6-3v10l-6-3"/>',notes:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8m-8 4h8m-8 4h5"/>',browser:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>'};
function icon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${art[id]||art.leaf}</svg>`}
const defaults=['快捷菜单','返回','边缘快捷栏','打开空叶软件页面','通知栏'];
const states=[0,1].map((_,i)=>({page:i?'settings':'ball',size:40,opacity:69,gap:0,snap:true,fade:true,haptic:true,enhanced:true,color:'#28765a',gestures:[...defaults],theme:'跟随系统',image:null,permissions:[true,false,true],running:true}));
const titles={home:'空叶悬浮球',ball:'悬浮球',settings:'设置'};
const notes=['<b>关联更清楚：</b>预览、颜色、大小、透明度和位置属于同一张卡片。空闲淡化紧跟透明度，自动吸边紧跟边框距离；触感反馈放在手势组内。','<b>分组按用途：</b>显示与应用管理显示范围，界面主题控制软件配色，悬浮球维护放找回和重置，关于与更新放版本和项目入口。'];
document.querySelector('#board').innerHTML=states.map((s,i)=>`<article class="concept"><div class="concept-title">${i?'设置页 · 按用途分组':'悬浮球页 · 强化预览与参数的联系'}<span>0${i+1}</span></div><section class="phone" data-phone="${i}"><div class="status"><span>9:41</span><svg viewBox="0 0 50 12" fill="currentColor"><path d="M1 9h2v2H1Zm4-3h2v5H5Zm4-3h2v8H9Zm4-3h2v11h-2Z"/><path d="M22 4q6-6 12 0l-2 2q-4-4-8 0Zm4 4q2-2 4 0l-2 3Z"/><rect x="38" y="2" width="10" height="7" rx="2"/></svg></div><header class="header"><h2>${titles[s.page]}</h2><small>空叶</small></header><main class="viewport"></main><nav class="nav">${[['home','leaf','首页'],['ball','ball','悬浮球'],['settings','settings','设置']].map(([key,ic,n])=>`<button data-tab="${key}"><span class="nav-icon">${icon(ic)}</span>${n}</button>`).join('')}</nav><div class="homebar"></div></section><p class="design-note">${notes[i]}</p></article>`).join('');
function toggle(key,label,s){return `<button class="toggle ${s[key]?'':'off'}" data-toggle="${key}" aria-label="${label}" aria-pressed="${s[key]}"></button>`}
function slider(key,title,min,max,s,unit){return `<div class="control-head"><label for="${key}-${states.indexOf(s)}">${title}</label><output data-output="${key}">${s[key]}${unit}</output></div><input id="${key}-${states.indexOf(s)}" type="range" data-slider="${key}" data-unit="${unit}" min="${min}" max="${max}" value="${s[key]}">`}
function ballPage(s){return `<section class="card appearance-card"><div class="card-title"><b>外观与位置</b><span>调整后立即预览</span></div><div class="preview"><div class="grid"></div><span class="label">位置预览</span><span class="screen-edge"></span><span class="edge-label">屏幕边缘</span><div class="ball" style="width:${s.size}px;height:${s.size}px;opacity:${s.opacity/100};right:${Math.max(s.gap,12-s.size)}px;background:${s.image?'transparent':s.color}">${s.image?'<img src="'+s.image+'" alt="自定义悬浮球">':icon('leaf')}</div><span class="preview-note">小叶靠边显示<br>大小与位置随下方设置变化</span></div><div class="style-row"><div class="swatches">${['#28765a','#567aab','#8d70a6','#d19251','#414e48'].map((c,k)=>`<button class="swatch ${s.color===c&&!s.image?'active':''}" style="--color:${c}" data-color="${c}" aria-label="${['苔绿','雾蓝','藤紫','秋杏','墨黑'][k]}"></button>`).join('')}</div><button class="image-button" data-action="art">${icon('image')}自定义图片 / GIF</button></div><div class="adjustments"><div class="control-group">${slider('size','大小',36,150,s,' dp')}</div><div class="control-group">${slider('opacity','不透明度',30,100,s,'%')}<div class="related-toggle"><span>空闲时淡化 <small>3 秒未操作时降低透明度</small></span>${toggle('fade','空闲时淡化',s)}</div></div><div class="control-group">${slider('gap','边框距离',-100,0,s,' dp')}<div class="related-toggle"><span>自动吸边 <small>松手后贴近屏幕边缘</small></span>${toggle('snap','自动吸边',s)}</div></div></div></section><h3 class="section-title">手势操作 <span class="hint-inline">定义怎样使用小叶</span></h3><div class="card gesture-card">${['单击','双击','长按','上划','下划'].map((n,j)=>`<div class="setting-row clickable" data-action="gesture" data-index="${j}"><span class="name">${n}</span><span class="tail">${s.gestures[j]}${icon('next')}</span></div>`).join('')}<div class="setting-row"><div><div class="name">触感反馈</div><div class="sub">操作时提供轻微振动</div></div>${toggle('haptic','触感反馈',s)}</div></div><p class="gesture-note">按住小叶约 0.3 秒即可拖动。拖动中停住，十字变黄后拖出矩形，松手即截图。</p><button class="reset-button" data-action="reset-gestures">恢复默认手势</button>`}
function settingRow(ic,title,sub,tail,action,extra=''){return `<div class="setting-row ${action?'clickable':''}" ${action?'data-action="'+action+'"':''} ${extra}><div class="row-leading">${ic?'<span class="leading-icon">'+icon(ic)+'</span>':''}<div><div class="name">${title}</div>${sub?'<div class="sub">'+sub+'</div>':''}</div></div><div class="tail">${tail||''}${action?icon('next'):''}</div></div>`}
function settingsPage(s){return `<div class="settings-first"><h3 class="section-title">显示与应用 <span class="hint-inline">小叶出现在哪里</span></h3><div class="card settings-card">${settingRow('layers','增强悬浮层','无障碍开启时，在更多界面显示',toggle('enhanced','增强悬浮层',s))}${settingRow('apps','特定应用中的悬浮球','为不同应用设置显示方式','','rules')}</div><h3 class="section-title">界面主题</h3><div class="card settings-card">${settingRow('theme','深色模式','调整空叶软件界面的配色',s.theme,'theme')}</div><h3 class="section-title">悬浮球维护</h3><div class="card settings-card">${settingRow('recover','找回悬浮球','暂时显示小叶并移回屏幕内','','recover')}${settingRow('position','重置位置','恢复悬浮球的默认停靠位置','','reset-position')}</div><h3 class="section-title">关于与更新</h3><div class="card settings-card">${settingRow('update','检查更新','', 'v1.16.2','update')}${settingRow('github','GitHub','查看项目源码与发布记录','','github')}${settingRow('info','关于空叶','使用帮助与版本信息','','about')}</div><p class="version">空叶悬浮球 · 一片小叶，随处可用</p></div>`}
function homePage(s){return `<div class="card"><div class="home-status"><span class="brand-circle">${icon('leaf')}</span><div><strong>${s.running?'● 运行中':'○ 未开启'}</strong><p>${s.running?'轻点小叶，随时打开工具':'开启后可在应用间使用'}</p></div></div><button class="primary home-start" data-action="running">${s.running?'暂停悬浮球':'开启悬浮球'}</button></div><h3 class="section-title">权限</h3><div class="card home-permission">${[['悬浮窗','让小叶显示在其他应用上方'],['无障碍服务','导航、截图与长截图需要'],['通知','显示运行状态与停止入口']].map(([n,d],j)=>settingRow(null,n,d,`<button class="small-link" data-action="permission" data-index="${j}">${s.permissions[j]?'✓ 已开启':'去开启'}</button>`)).join('')}</div><h3 class="section-title">工具</h3><div class="card tools-grid">${[['region','区域截图'],['screen','长截图'],['record','录屏'],['image','录制 GIF'],['apps','最近应用'],['leaf','常用应用'],['notes','便签'],['browser','浏览器']].map(([ic,n])=>`<button data-action="tool" data-label="${n}"><span>${icon(ic)}</span>${n}</button>`).join('')}</div>`}
function phone(i){return document.querySelector('[data-phone="'+i+'"]')}
function render(i,key=states[i].page){let p=phone(i),s=states[i];s.page=key;p.querySelector('.shade')?.remove();p.querySelector('.header h2').textContent=titles[key];p.querySelector('.viewport').innerHTML=({home:homePage,ball:ballPage,settings:settingsPage}[key])(s);p.querySelector('.viewport').scrollTop=0;p.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===key));p.classList.toggle('dark',s.theme==='深色模式')}
function toast(i,text){let p=phone(i);p.querySelector('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.textContent=text;p.appendChild(n);setTimeout(()=>n.remove(),2300)}
function sheet(i,title,html){let p=phone(i);p.querySelector('.shade')?.remove();let n=document.createElement('div');n.className='shade';n.innerHTML=`<div class="sheet"><header class="sheet-head"><h3>${title}</h3><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></header>${html}</div>`;n.addEventListener('click',e=>{if(e.target===n)n.remove()});p.appendChild(n)}
function saveScrollRender(i){let pos=phone(i).querySelector('.viewport').scrollTop;render(i);phone(i).querySelector('.viewport').scrollTop=pos}
document.addEventListener('input',e=>{let p=e.target.closest('[data-phone]');if(!p||!e.target.dataset.slider)return;let s=states[Number(p.dataset.phone)],key=e.target.dataset.slider;s[key]=Number(e.target.value);p.querySelector('[data-output="'+key+'"]').textContent=e.target.value+e.target.dataset.unit;let ball=p.querySelector('.ball');ball.style.width=s.size+'px';ball.style.height=s.size+'px';ball.style.opacity=s.opacity/100;ball.style.right=Math.max(s.gap,12-s.size)+'px';if(key==='gap')p.querySelector('.preview-note').innerHTML=s.gap<0?'负值让小叶部分藏在边缘<br>当前边框距离 '+s.gap+' dp':'小叶靠边显示<br>大小与位置随下方设置变化'});
document.addEventListener('click',e=>{let b=e.target.closest('[data-tab],[data-action],[data-toggle],[data-color]');if(!b)return;let p=b.closest('[data-phone]');if(!p)return;let i=Number(p.dataset.phone),s=states[i],a=b.dataset.action;
if(b.dataset.tab){render(i,b.dataset.tab);return}if(b.dataset.color){if(s.image?.startsWith('blob:'))URL.revokeObjectURL(s.image);s.image=null;s.color=b.dataset.color;saveScrollRender(i);return}if(b.dataset.toggle){s[b.dataset.toggle]=!s[b.dataset.toggle];b.classList.toggle('off',!s[b.dataset.toggle]);b.setAttribute('aria-pressed',String(s[b.dataset.toggle]));return}
switch(a){case'close':p.querySelector('.shade')?.remove();break;
case'gesture':s.editGesture=Number(b.dataset.index);sheet(i,['单击','双击','长按','上划','下划'][s.editGesture],['快捷菜单','返回','边缘快捷栏','打开空叶软件页面','区域截图','长截图','录屏','录制 GIF','通知栏','不执行'].map(n=>`<div class="sheet-row" data-action="choose-gesture" data-choice="${n}"><span>${n}</span><span class="selected">${s.gestures[s.editGesture]===n?icon('check'):''}</span></div>`).join(''));break;
case'choose-gesture':s.gestures[s.editGesture]=b.dataset.choice;saveScrollRender(i);break;
case'reset-gestures':s.gestures=[...defaults];saveScrollRender(i);toast(i,'演示：手势已恢复默认');break;
case'art':sheet(i,'自定义悬浮球',`<p class="mini-message">支持透明图片与 GIF。可以先选择一种图案查看预览，也可以从本地选择。</p><div class="choice-image">${['leaf','image','ball'].map(ic=>`<button data-action="sample-art" data-icon="${ic}" aria-label="预览${ic}">${icon(ic)}</button>`).join('')}</div><button class="primary" data-action="choose-file">选择本地图片 / GIF</button><input class="file-input" type="file" accept="image/*" aria-label="本地图片">`);break;
case'sample-art':p.querySelector('.shade')?.remove();s.image=null;saveScrollRender(i);p.querySelector('.ball').innerHTML=icon(b.dataset.icon);toast(i,'演示图案已预览');break;
case'choose-file':p.querySelector('.file-input').click();break;
case'theme':sheet(i,'深色模式',['跟随系统','浅色模式','深色模式','定时开启'].map(n=>`<div class="sheet-row" data-action="choose-theme" data-choice="${n}"><span>${n}</span><span class="selected">${s.theme===n?icon('check'):''}</span></div>`).join(''));break;
case'choose-theme':s.theme=b.dataset.choice;saveScrollRender(i);if(s.theme==='定时开启')sheet(i,'定时开启',`<p class="mini-message">按手机本地时间设置深色模式时段。</p><div class="schedule-inputs"><label>开始时间<input type="time" value="22:00"></label><label>结束时间<input type="time" value="07:00"></label></div><button class="primary" data-action="close">确定</button>`);break;
case'rules':sheet(i,'特定应用中的悬浮球',`<p class="mini-message">为每个应用设置小叶的显示方式。</p>${['微信','浏览器','相册','设置'].map(n=>`<div class="sheet-row"><span>${n}</span><select aria-label="${n}中的显示"><option>正常显示</option><option>隐身可用</option><option>禁用</option></select></div>`).join('')}`);break;
case'recover':toast(i,'演示：临时显示悬浮球并移回屏幕内');break;
case'reset-position':sheet(i,'重置悬浮球位置',`<p class="mini-message">将悬浮球恢复到默认停靠位置。</p><button class="primary" data-action="confirm-position">重置位置</button>`);break;
case'confirm-position':s.gap=0;p.querySelector('.shade')?.remove();toast(i,'演示：位置已重置');break;
case'update':sheet(i,'检查更新',`<p class="mini-message">当前版本 v1.16.2</p><div style="padding:20px 0;text-align:center;color:var(--green)">${icon('check').replace('<svg ','<svg style="width:35px;height:35px" ')}<p style="font-size:12px">演示版本已是最新</p></div><button class="primary" data-action="close">知道了</button>`);break;
case'github':case'about':sheet(i,a==='github'?'GitHub 项目':'关于空叶',`<div style="text-align:center;padding:17px 0">${icon('leaf').replace('<svg ','<svg style="width:42px;height:42px;color:var(--green)" ')}<p style="font-size:15px;font-weight:600">空叶悬浮球</p><p class="mini-message">一片小叶，随处可用。<br>${a==='github'?'Mayleaves / KongyeFloat':'v1.16.2'}</p></div><button class="primary" data-action="close">返回</button>`);break;
case'running':s.running=!s.running;saveScrollRender(i);break;
case'permission':s.permissions[Number(b.dataset.index)]=!s.permissions[Number(b.dataset.index)];saveScrollRender(i);toast(i,'演示状态已更新');break;
case'tool':toast(i,'查看布局演示：'+b.dataset.label);break;
}});
document.addEventListener('change',e=>{if(!e.target.matches('.file-input'))return;let file=e.target.files[0];if(!file)return;let p=e.target.closest('[data-phone]'),i=Number(p.dataset.phone);if(!file.type.startsWith('image/')){toast(i,'请选择图片或 GIF');return}if(states[i].image?.startsWith('blob:'))URL.revokeObjectURL(states[i].image);states[i].image=URL.createObjectURL(file);saveScrollRender(i)});
states.forEach((_,i)=>render(i));
